    ;
  // 读取下位机返回的信息，并在串口输出
  len = 0;
  CAN.readMsgBuf(&len, recvBuf);
  int id = CAN.getCanId();
  Serial.print("id : "); Serial.println(id);
  Serial.println((char *)recvBuf);
