#include <SPI.h>
#include "mcp2515_can.h"

const int SPI_CS_PIN = 9;
const int CAN_INT_PIN = 2;
mcp2515_can CAN(SPI_CS_PIN);  // Set CS pin

unsigned char recvBuf[8];  // 接受信息缓存
uint8_t len;               // 接收到的字节数
const uint8_t slaveID = 1; // 下位机 CAN ID
bool flagRecv;

void setup() {
  Serial.begin(1000000);
  while (!Serial) {};

  // Init can bus : baudrate = 1000k
  while (CAN_OK != CAN.begin(CAN_1000KBPS)) {
    Serial.println("CAN init fail, retry...");
    delay(100);
  }
  Serial.println("CAN init ok!\n");
  // 设置监听CAN的外部中断
  attachInterrupt(digitalPinToInterrupt(CAN_INT_PIN), posMonitor, FALLING);
}

// 监听CAN的外部中断
void posMonitor() {
  flagRecv = true;
}

void loop() {
  if (flagRecv) {
    flagRecv = 0;  // clear flag
    while (CAN_MSGAVAIL == CAN.checkReceive()) {
      // 读取数据到缓冲区
      CAN.readMsgBuf(&len, recvBuf);
      // 把缓冲区二进制数据转换为浮点数
      float pos;
      memcpy(&pos, &recvBuf[0], len);
      Serial.println(pos);
      // 返回处理成功的信息
      CAN.MCP_CAN::sendMsgBuf(slaveID, 0, 2, "OK");
    }
  }
}

float inputPos() {
  while (!Serial.available())
    ;

  // 从ASCII数据流中解析浮点数
  float res = Serial.parseFloat();
  // 读取换行符 '\n'
  Serial.read();
  return res;
}

